"""Verify penetrant coverage and magnetic unoriented-direction arithmetic."""

import json
import math
from pathlib import Path

from matintegrity.models.surface_examination import (
    LiquidPenetrantExamination,
    MagneticParticleExamination,
    liquid_penetrant_summary,
    magnetic_particle_summary,
)

ROOT = Path(__file__).resolve().parents[1]
OUTPUT = ROOT / "validation/surface_examination_math.json"
EVIDENCE = {
    "source_id": "authored-surface-validation",
    "origin": "synthetic",
    "citation": "independent synthetic verification generated by this project",
}
AREA = {
    "area_id": "area-a",
    "physical_location_id": "location-a",
    "target_area_m2": 2.0,
    "examined_area_m2": 1.5,
    "unexamined_basis": "authored inaccessible segment",
}


def main():
    penetrant = LiquidPenetrantExamination.model_validate(
        {
            "examination_id": "authored-pt",
            "procedure_id": "authored-procedure",
            "procedure_revision": "1",
            "penetrant_type": "visible",
            "removal_method": "solvent_removable",
            "cleaner_batch_id": "c",
            "penetrant_batch_id": "p",
            "remover_or_emulsifier_batch_id": "r",
            "developer_batch_id": "d",
            "surface_material_id": "m",
            "surface_condition": "authored",
            "precleaning_basis": "authored",
            "drying_basis": "authored",
            "examination_temperature_K": 295.0,
            "penetrant_dwell_s": 600.0,
            "excess_removal_basis": "authored",
            "developer_application_basis": "authored",
            "development_time_s": 600.0,
            "observation_lighting_basis": "authored",
            "final_cleaning_basis": "authored",
            "areas": [AREA],
            "indications": [],
            "areas_mutually_exclusive_reviewed": True,
            "material_and_consumables_compatibility_reviewed": True,
            "process_sequence_reviewed": True,
            "temperature_and_times_reviewed": True,
            "surface_condition_reviewed": True,
            "indication_mapping_reviewed": True,
            "negative_result_reviewed": True,
            "evidence": [EVIDENCE],
        }
    )
    pt_result = liquid_penetrant_summary(penetrant)
    magnetic_values = {
        "examination_id": "authored-mt",
        "procedure_id": "authored-procedure",
        "procedure_revision": "1",
        "surface_material_id": "m",
        "surface_condition": "authored",
        "particle_medium": "dry",
        "particle_batch_id": "p",
        "observation_lighting_basis": "authored",
        "minimum_direction_separation_rad": 1.0,
        "directional_coverage_requirement_basis": "authored requirement",
        "areas": [AREA],
        "magnetization_passes": [
            {
                "pass_id": "a",
                "area_id": "area-a",
                "technique": "authored",
                "current_mode": "ac",
                "field_direction_rad": 0.1,
                "field_adequacy_basis": "authored",
                "equipment_id": "e",
            },
            {
                "pass_id": "b",
                "area_id": "area-a",
                "technique": "authored",
                "current_mode": "ac",
                "field_direction_rad": math.pi - 0.2,
                "field_adequacy_basis": "authored",
                "equipment_id": "e",
            },
        ],
        "indications": [],
        "areas_mutually_exclusive_reviewed": True,
        "ferromagnetic_applicability_reviewed": True,
        "equipment_and_media_reviewed": True,
        "field_adequacy_reviewed": True,
        "directional_requirement_reviewed": True,
        "surface_condition_reviewed": True,
        "indication_mapping_reviewed": True,
        "negative_result_reviewed": True,
        "evidence": [EVIDENCE],
    }
    mt_result = magnetic_particle_summary(MagneticParticleExamination.model_validate(magnetic_values))
    computed_separation = mt_result.values["maximum_unoriented_direction_separation_rad_by_area"]["area-a"]
    expected_separation = 0.3
    if (
        abs(pt_result.values["coverage_fraction"] - 0.75) > 1e-15
        or abs(computed_separation - expected_separation) > 1e-15
        or mt_result.status != "needs_data"
    ):
        raise ValueError("surface-examination arithmetic identity failed")
    report = {
        "schema": "matintegrity.surface_examination_math.v1",
        "penetrant_expected_coverage_fraction": 0.75,
        "penetrant_computed_coverage_fraction": pt_result.values["coverage_fraction"],
        "magnetic_expected_unoriented_separation_rad": expected_separation,
        "magnetic_computed_unoriented_separation_rad": computed_separation,
        "magnetic_insufficient_direction_area_ids": mt_result.values["insufficient_direction_area_ids"],
        "qualification": (
            "Synthetic arithmetic and contract verification only; no penetrant or magnetic-particle "
            "procedure, consumable, field, inspector, detection capability or acceptance is qualified."
        ),
    }
    OUTPUT.write_text(json.dumps(report, indent=2), encoding="utf-8")
    print(json.dumps(report, indent=2))


if __name__ == "__main__":
    main()
